anchors = {}
for f in files:
    s = open(f).read()
    a = set()
    for m in re.finditer(r"^#{1,6} (.+)$", s, re.M):
        a.add(slug(m.group(1)))
    a |= set(re.findall(r'<a id="([^"]+)"', s))
    anchors[os.path.normpath(f)] = a
bad = 0
for f in files:
    s = re.sub(r"```.*?```", "", open(f).read(), flags=re.S)
    for m in re.finditer(r"\]\(([^)\s]+)\)", s):
        url = m.group(1)
        if url.startswith(("http", "mailto")): continue
        path, _, frag = url.partition("#")
        target = os.path.normpath(os.path.join(os.path.dirname(f), path)) if path else os.path.normpath(f)
        if not os.path.exists(target):
            print("MISSING FILE", f, url); bad += 1; continue
        if frag and target in anchors and frag not in anchors[target]:
            print("MISSING ANCHOR", f, url); bad += 1
print("bad:", bad)
